const mockOrderErrorScenarioBySaleId = new Map(
  mockOrderErrorScenarios.map((scenario) => [scenario.saleId, scenario])
);

const triggeredMockOrderErrorSaleIds = new Set<string>();

const saleResponses: SaleResponse[] = [
  sale,
  {
    ...sale,
    saleId: 2,
    title: `${sale.title} - 마감`,
    status: 'CLOSE',
    orderable: false,
    closesAt: '2026-08-01T23:59:59',
  },
  ...mockOrderErrorScenarios.map((scenario) => scenario.initialSale),
];

const saleResponseById = new Map(
  saleResponses.map((saleResponse) => [
    String(saleResponse.saleId),
    saleResponse,
  ])
);

function findRequiredNoticeError(
  saleResponse: SaleResponse,
  noticeAcceptances: NoticeAcceptance[] = []
) {
  const noticeAcceptanceById = new Map(
    noticeAcceptances.map((noticeAcceptance) => [
      noticeAcceptance.noticeId,
      noticeAcceptance,
    ])
  );

  const hasVersionChanged = saleResponse.notices.some((notice) => {
    const noticeAcceptance = noticeAcceptanceById.get(notice.noticeId);

    return (
      noticeAcceptance !== undefined &&
      noticeAcceptance.version !== notice.version
    );
  });

  if (hasVersionChanged) {
    return {
      code: 'COMMERCE_NOTICE_VERSION_CHANGED',
      message: '유의사항이 변경되었습니다. 다시 확인해 주세요.',
      status: 409,
    };
  }

  const hasUncheckedRequiredNotice = saleResponse.notices.some((notice) => {
    const noticeAcceptance = noticeAcceptanceById.get(notice.noticeId);

    return notice.required && noticeAcceptance?.accepted !== true;
  });

  if (hasUncheckedRequiredNotice) {
    return {
      code: 'COMMERCE_NOTICE_REQUIRED',
      message: '필수 확인 항목에 모두 동의해 주세요.',
      status: 400,
    };
  }

  return null;
}

function getSaleResponseForMockScenario(
  saleId: string,
  saleResponse: SaleResponse
) {
  const mockOrderErrorScenario = mockOrderErrorScenarioBySaleId.get(saleId);

  if (!mockOrderErrorScenario) {
    return saleResponse;
  }

  return triggeredMockOrderErrorSaleIds.has(saleId)
    ? mockOrderErrorScenario.refetchedSale
    : mockOrderErrorScenario.initialSale;
}

function createCommerceErrorResponse({
  errorCode,
  message,
  status,
}: MockOrderErrorScenario) {
  return HttpResponse.json(
    {
      code: String(errorCode),
      message,
    },
    { status }
  );
}

