export const handlers = [
  http.get('*/v1/commerce/sales/:saleId', async ({ params }) => {
    await delay(250);

    const saleId = Array.isArray(params.saleId)
      ? params.saleId[0]
      : params.saleId;
    const saleResponse = saleResponseById.get(String(saleId));

    if (!saleResponse) {
      return HttpResponse.json(
        {
          code: 'COMMERCE_SALE_NOT_FOUND',
          message: '판매 정보를 찾을 수 없습니다.',
        },
        { status: 404 }
      );
    }

    return HttpResponse.json({
      result: getSaleResponseForMockScenario(String(saleId), saleResponse),
    });
  }),
  http.get('*/v1/commerce/orders', async () => {
    await delay(250);

    return HttpResponse.json({
      result: mockOrderListResponse,
    });
  }),
  http.post('*/v1/commerce/orders', async ({ request }) => {
    await delay(250);

    const requestBody = (await request.json()) as Partial<CreateOrderRequest>;
    const saleId = String(requestBody.saleId);
    const saleResponse = saleResponseById.get(saleId);

    if (!saleResponse) {
      return HttpResponse.json(
        {
          code: 'COMMERCE_SALE_NOT_FOUND',
          message: '판매 정보를 찾을 수 없습니다.',
        },
        { status: 404 }
      );
    }

    if (!saleResponse.orderable) {
      return HttpResponse.json(
        {
          code: 'COMMERCE_SALE_NOT_ORDERABLE',
          message: '지금은 주문할 수 있는 판매가 아닙니다.',
        },
        { status: 409 }
      );
    }

    const mockOrderErrorScenario = mockOrderErrorScenarioBySaleId.get(saleId);

    if (mockOrderErrorScenario) {
      triggeredMockOrderErrorSaleIds.add(saleId);

      return createCommerceErrorResponse(mockOrderErrorScenario);
    }

    if (requestBody.contactSharingConsent !== true) {
      return HttpResponse.json(
        {
          code: 'COMMERCE_CONSENT_REQUIRED',
          message: '개인정보 제공 동의가 필요합니다.',
        },
        { status: 400 }
      );
    }

    const noticeError = findRequiredNoticeError(
      saleResponse,
      requestBody.noticeAcceptances
    );

    if (noticeError) {
      return HttpResponse.json(
        {
          code: noticeError.code,
          message: noticeError.message,
        },
        { status: noticeError.status }
      );
    }

    return HttpResponse.json({
      result: {
        orderNumber: 'SR-20260813-000001',
        idempotentReplay: false,
      },
    });
  }),
];
